text:
.page {
  --settings-bg: var(--color-settings-settings-bg-1);
  --settings-elevated: var(--color-settings-settings-elevated-2);
  --settings-surface: var(--color-settings-settings-surface-3);
  --settings-inset: var(--color-settings-settings-inset-4);
  --settings-border: var(--color-settings-settings-border-5);
  --settings-strong: var(--color-settings-settings-strong-6);
  --settings-text: var(--color-settings-settings-text-7);
  --settings-muted: var(--color-settings-settings-muted-8);
  --settings-purple: var(--color-settings-settings-purple-9);
  --settings-pink: var(--color-settings-settings-pink-10);
  --settings-green: var(--color-settings-settings-green-11);
  --settings-red: var(--color-settings-settings-red-12);
  --settings-yellow: var(--status-warning-text);
}
:global([data-theme="dark"]) .page {
  --settings-bg: var(--color-settings-settings-bg-13);
  --settings-elevated: var(--color-settings-settings-elevated-14);
  --settings-surface: var(--color-settings-settings-surface-15);
  --settings-inset: var(--color-settings-settings-inset-16);
  --settings-border: var(--color-settings-settings-border-17);
  --settings-strong: var(--color-settings-settings-strong-18);
  --settings-text: var(--color-settings-settings-text-19);
  --settings-muted: var(--color-settings-settings-muted-20);
  --settings-purple: var(--color-settings-settings-purple-21);
  --settings-pink: var(--color-settings-settings-pink-22);
  --settings-green: var(--color-settings-settings-green-23);
  --settings-red: var(--color-settings-settings-red-24);
  --settings-yellow: var(--color-settings-settings-yellow-25);
}
.page :is(button, a, input, select, summary, [tabindex]):focus-visible {
  outline: 2px solid var(--settings-pink);
  outline-offset: 3px;
}
.navIndicator {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 1;
  border-radius: 999px;
  background: var(--link);
  opacity: 0;
  pointer-events: none;
  transition:
    transform 280ms cubic-bezier(0.22, 1, 0.36, 1),
    width 280ms cubic-bezier(0.22, 1, 0.36, 1),
    height 280ms cubic-bezier(0.22, 1, 0.36, 1),
    background-color 280ms ease;
}
.navIndicator[data-ready="true"] {
  opacity: 1;
}
.navIndicator[data-danger="true"] {
  background: var(--settings-red);
}
.page :is(button, input, select):disabled {
  opacity: 0.45;
  cursor: not-allowed;
  pointer-events: auto;
  box-shadow: var(--appearance-shadow, none);
}
.page button:disabled:hover {
  background-color: transparent;
}
.dialog::backdrop {
  background: var(--color-settings-background-36);
  backdrop-filter: blur(4px);
}
@media (prefers-reduced-motion: reduce) {
  .page *,
  .page *::before,
  .page *::after {
    scroll-behavior: auto;
    transition: none;
    animation: none;
  }
}

:global(html[data-workspace][data-appearance="vercel"]) .page {
  --settings-bg: var(--background);
  --settings-elevated: var(--card);
  --settings-surface: var(--card);
  --settings-inset: var(--surface);
  --settings-border: var(--border);
  --settings-strong: var(--border-hover);
  --settings-text: var(--foreground);
  --settings-muted: var(--body);
  --settings-purple: var(--link);
  --settings-pink: var(--ring);
  --settings-green: var(--status-success-text);
  --settings-red: var(--settings-danger-text, var(--status-error-text));
  --settings-yellow: var(--warning);
}
:global(html[data-workspace][data-appearance="vercel"]) .eyebrow {
  color: var(--coral);
}
:global(html[data-workspace][data-appearance="vercel"])
  :is(.primary, .secondary, .dangerButton) {
  border-radius: var(--appearance-control-radius);
}

:global(html[data-workspace][data-appearance="vercel"]) .page .dangerButton {
  --control-border: var(--settings-danger-border);
  --button-interaction-color: var(--settings-red);
  --neutral-control-hover: var(--settings-danger-background);
  --neutral-control-pressed: color-mix(
    in srgb,
    var(--settings-red) 16%,
    transparent
  );
  --neutral-control-border-hover: var(--settings-red);
}
